;------------------------------------[ SPLIT TIPS ON COLLISION ]------------------------------------

SPLTTP:
; [note] Split the tips off a special-rock cluster on collision; frees the linked objects
L4800:  LDA OBJ,Y               ;GET PIX CODE
L4803:  AND #$3C                ;ISOLATE LINK FIELD
L4805:  LSR A                   ;MAKE IT RELATIVE TO 0
L4806:  LSR A
L4807:  TAX                     ;POINT TO OBJECT PARAMS
L4808:  LDA SRTIME,X            ;GET CONTROL BYTE
L480B:  BPL SPLTTP_1            ;NOT WAITING
L480D:  STX XT                  ;SAVE INDEX
L480F:  LDA #$05                ;POINTS
L4811:  JSR GPTS                ;($48B2) GIVE POINTS
L4814:  JSR SEARCH              ;($6D6C) LOOK FOR FREE ENTRY
L4817:  INC NROCKS              ;ADD ANOTHER TO TOTAL
L481A:  LDA OBJ,Y               ;GET PIX CODE AGAIN
L481D:  PHA                     ;SAVE IT
L481E:  JSR CPYPOS              ;($6210) COPY ALL PARAMATERS
L4821:  PLA                     ;(CPYPOS BLITZES 'OBJ')
L4822:  STA OBJ,X               ;(SO PASS THE OLD PIX CODE
L4825:  LDA #$00
L4827:  STA OBJ,Y               ;CAUSE A BIG EXPLOSION
L482A:  LDX XT                  ;RESTORE X

SPLTTP_3:
L482C:  LDA SRTIME,X            ;FREE ALL THE OBJECTS IN THE CLUSTER
L482F:  BPL SPLTTP_2            ;DONE
L4831:  PHA                     ;SAVE INDEX
L4832:  LDA #$7F
L4834:  STA SRTIME,X            ;RELEASE AS BIG OBJECT WITH MAX TIME
L4837:  PLA                     ;RETRIEVE INDEX
L4838:  LSR A                   ;COMPUTE THE LINK VALUE
L4839:  AND #$0F                ;MASK
L483B:  TAX                     ;X NOW HAS LINK TO NEXT OBJECT
L483C:  BPL SPLTTP_3            ;(ALWAYS)

SPLTTP_1:
L483E:  LSR A                   ;PUT SIZE BIT INTO CARRY
L483F:  BCS SPLTTP_4            ;ITS A BIG ONE
L4841:  LDA #$00
L4843:  STA SRTIME,X            ;DE-ACTIVATE CONTROL BYTE
L4846:  LDA #$20
L4848:  JSR GPTS                ;($48B2) GIVE 'EM 200 POINTS
L484B:  JSR DIASND              ;($49A4) GIVE SOUND FOR DIAMOND

SPLTTP_2:
L484E:  LDX TEMP3               ;RESTORE X
L4850:  RTS                     ;EXIT

SPLTTP_4:
L4851:  LDA #$10                ;GIVE 'EM 200
L4853:  STX XT                  ;SAVE X
L4855:  JSR GPTS                ;($48B2)
L4858:  JSR SEARCH              ;($6D6C) FIND A FREE ENTRY
L485B:  JSR CPYPOS              ;($6210) COPY POSITION PARAMETERS
L485E:  INC NROCKS              ;ADD 1 TO TOTAL OBJECTS
L4861:  INC SPROCK              ;ADD 1 TO SPECIAL COUNT
L4864:  LDA XT                  ;GET CONTROL BYTE INDEX
L4866:  ASL A
L4867:  ASL A
L4868:  ORA #$42                ;SAY ITS A SPECIAL ROCK BUT A SMALL ONE
L486A:  STA OBJ,X
L486D:  STX R0                  ;SAVE X
L486F:  LDX XT                  ;POINT TO CONTROL BYTE
L4871:  LDA #$7E
L4873:  STA SRTIME,X
L4876:  LDA ANGLE
L4878:  ADC #$20                ;POINT IT AWAY APPROX 45 DEGREES
L487A:  STA SRANG,X
L487D:  JSR FREESR              ;($48A7) FIND A FREE SPECIAL ROCK ENTRY
L4880:  STX XT                  ;SAVE ENTRY POINTER
L4882:  LDX R0                  ;POINT TO OBJ
L4884:  JSR SEARC1              ;($6D6E) LOOK FOR NEXT FREE OBJ
L4887:  JSR CPYPOS              ;($6210) MOVE POSITION PARAMETERS
L488A:  INC NROCKS              ;ADD 1 TO TOTAL OBJECT COUNT
L488D:  LDA XT                  ;GET LINK TO SPECIAL
L488F:  ASL A
L4890:  ASL A
L4891:  ORA #$42
L4893:  STA OBJ,X               ;SELECT SPECIAL ROCK
L4896:  LDX XT                  ;POINT TO SPECIAL CONTROLS
L4898:  LDA #$7E                ;ACTIVATE OBJECT
L489A:  STA SRTIME,X
L489D:  LDA ANGLE
L489F:  SBC #$20                ;POINT AWAY APPROX 45 DEGREES
L48A1:  STA SRANG,X
L48A4:  LDX TEMP3               ;RESTORE X
L48A6:  RTS                     ;EXIT

FREESR:
; [note] Find a free special-rock control entry, 6 down to 0; $FF if none
L48A7:  LDX #$06                ;MAXIMUM # OF SPECIAL ROCKS ALLOWED

FREESR_2:
L48A9:  LDA SRTIME,X            ;FIND AN EMPTY SLOT
L48AC:  BEQ TRIROT_RTS_0        ;GOT ONE
L48AE:  DEX
L48AF:  BPL FREESR_2            ;KEEP LOOKING

TRIROT_RTS_0:
; placed by hand: TRIROT.MAC:214 `RTS.0: RTS`, FREESR's exit. A bare RTS matches at every RTS in the ROM, so the order prune drops it. DSTRD0.MAC has its own RTS.0 (placed at $669C as DSTRD0_RTS.0); qualified by module the same way
L48B1:  RTS

GPTS:
; [note] Award points for a hit, but not when the saucer made it
L48B2:  LDX TEMP3
L48B4:  BEQ GPTS_1              ;SHIP. GIVE POINTS
L48B6:  CPX #$04                ;SHIP'S TORPEDOES?
L48B8:  BCC TRIROT_RTS_0        ;NO. NO POINTS

GPTS_1:
L48BA:  CLC
L48BB:  JMP POINTS              ;($6C60) GIVE POINTS

;------------------------------------------[ ATTACK SHIP ]------------------------------------------

ATTACK:
; [note] Steer special rock X toward the ship
L48BE:  STX R0                  ;SAVE X
L48C0:  LDY #$19                ;ASSUME WE WILL TRACK SHIP
L48C2:  STY R1                  ;INIT R1 FOR LATER
L48C4:  INC R9                  ;COUNT ATTACKING ENEMY
L48C6:  LDA OBJ,X               ;GET PIX CODE
L48C9:  LSR A
L48CA:  LSR A
L48CB:  AND #$0F
L48CD:  TAX                     ;POINT TO CONTROL BYTE
L48CE:  LDY SRTIME,X            ;GET CONTROL
L48D1:  CPY #$04                ;TIMED OUT?
L48D3:  BCC ATTACK_2            ;YEP. TRACK TO EDGE
L48D5:  LDA FRAME
L48D7:  AND #$0F                ;TIME OUT ?
L48D9:  BNE ATTACK_3            ;NOT HERE
L48DB:  TYA                     ;GET TIME
L48DC:  SEC
L48DD:  SBC #$02                ;TIME DOWN
L48DF:  STA SRTIME,X

ATTACK_3:
L48E2:  LDA SHPPIX              ;SHIP VISIBLE?
L48E5:  BEQ ATTACK_7            ;NOPE. FORCE A TIME OUT
L48E7:  BPL ATTACK_4            ;VISIBLE BUT BLOWING UP

ATTACK_7:
L48E9:  TYA                     ;GET CONTROL
L48EA:  AND #$01                ;KEEP SIZE
L48EC:  ORA #$02                ;AND A MINIMUM TIME (KEEPS IT .NE.)
L48EE:  STA SRTIME,X

ATTACK_2:
L48F1:  INC R1                  ;TRACK ON SNOW FLAKE

ATTACK_4:
L48F3:  LDY R1
L48F5:  STX XT                  ;SAVE X
L48F7:  LDX R0                  ;POINT TO POSITION PARAMETERS
L48F9:  JSR CPUTD               ;($4A1A)
L48FC:  JSR RTST                ;($49F5) DO RANGE
L48FF:  STA R3                  ;SAVE X DIFFERENCE
L4901:  LDA TEMP2
L4903:  STA R2
L4905:  LDA R1
L4907:  CLC
L4908:  ADC #$21                ;SKIP TO Y PARAMETERS
L490A:  TAY
L490B:  TXA
L490C:  ADC #$21
L490E:  TAX
L490F:  JSR CPUTD               ;($4A1A) COMPUTE Y DISTANCE
L4912:  JSR RTST                ;($49F5) RANGE IT
L4915:  JSR SCALER              ;($4A2A) SCALE IT, GET ARCTAN
L4918:  LDX XT                  ;RESTORE X
L491A:  STA R2                  ;SAVE ANGLE
L491C:  LDY #$19
L491E:  CPY R1                  ;TRACKING ON SHIP?
L4920:  BNE ATTACK_21           ;NO. ALWAYS TURN
L4922:  EOR #$80                ;FLIP IT 180
L4924:  SBC ANGLE               ;SEE HOW IT COMPARES WITH SHIP'S ANGLE
L4926:  BPL ATTACK_20
L4928:  EOR #$FF

ATTACK_20:
L492A:  CMP #$10                ;DON'T TURN IF SHIP IS POINTING AT ENEMY
L492C:  BCS ATTACK_21           ;GO AHEAD AND TURN
L492E:  LDA R2                  ;GET ANGLE
L4930:  SBC SRANG,X
L4933:  BPL ATTACK_22
L4935:  EOR #$FF

ATTACK_22:
L4937:  CMP #$40                ;IS OBJECT POINTING AT SHIP
L4939:  BCC ATTACK_18           ;YES. DON'T TURN

ATTACK_21:
L493B:  LDA R2                  ;RETRIEVE ANGLE
L493D:  SEC
L493E:  SBC SRANG,X             ;GET ABS(TARGET-CURRENT)
L4941:  STA R2                  ;SAVE SIGN
L4943:  BPL ATTACK_11           ;OK
L4945:  EOR #$FF                ;NEGATE IT

ATTACK_11:
L4947:  CMP #$08                ;DIFFERENCE > 8?
L4949:  BCC ATTACK_18           ;NOPE. DON'T TURN
L494B:  LDA #$01                ;PREPARE FOR SLOW TURN
L494D:  LDY #$19
L494F:  CPY R1                  ;TRACKING ON SHIP?
L4951:  BNE ATTACK_12           ;NO. SLOW TURNS
L4953:  LDX R9                  ;GET OBJ #
L4955:  CPX #$07                ;LIMIT IT
L4957:  BCC ATTACK_17
L4959:  LDX #$00

ATTACK_17:
L495B:  LDA AVEL,X              ;GET ANGULAR VELOCITY
L495E:  LDX XT                  ;RESTORE X

ATTACK_12:
L4960:  ASL R2                  ;GET SIGN
L4962:  BCC ATTACK_16           ;+
L4964:  EOR #$FF                ;NEGATE IT (CARRY SET FROM ABOVE)

ATTACK_16:
L4966:  ADC SRANG,X
L4969:  STA SRANG,X

ATTACK_18:
L496C:  LDA BINSCR
L496E:  ASL A
L496F:  CMP #$10                ;MAX IT OUT
L4971:  BCC ATTACK_19
L4973:  LDA #$0F

ATTACK_19:
L4975:  ADC #$1C                ;MINIMUM VELOCITY
L4977:  STA R1
L4979:  PHA
L497A:  LDA SRANG,X
L497D:  JSR COS                 ;($7134) GET COS(ANGLE)
L4980:  JSR MULT                ;($49B3)
L4983:  LDX R0                  ;RESTORE X
L4985:  STA XINC,X              ;SUPPLY NEW X INCREMENT
L4988:  PLA
L4989:  STA R1
L498B:  LDX XT
L498D:  LDA SRANG,X
L4990:  JSR SIN                 ;($7137)
L4993:  JSR MULT                ;($49B3)
L4996:  LDX R0
L4998:  STA YINC,X
L499B:  RTS

AVEL:
L499C:  .byte $01, $02, $03, $03, $03, $04, $04 ;.......

CKSUM0:
L49A3:  .byte $BA               ;.

DIASND:
; [note] Play the diamond sound when the last special rock of a cluster goes
L49A4:  DEC SPROCK
L49A7:  BNE DIASND_1            ;NOT LAST ONE
L49A9:  TYA                     ;SAVE Y
L49AA:  PHA
L49AB:  LDY #$3F                ;DIAMOND NOISE
