DIASND_1:
L49B2:  RTS

;-------------------------------------------[ MULTIPLY ]--------------------------------------------

MULT:
; AT EXIT:
; (A)=PRODUCT (SIGNED)
; Y,R1,R2,R3 DESTROYED
L49B3:  TAY                     ;SET CONDITION CODES
L49B4:  BPL MULT_1
L49B6:  EOR #$FF
L49B8:  CLC
L49B9:  ADC #$01

MULT_1:
L49BB:  STA R2
L49BD:  LDA #$00                ;INITIALIZE PRODUCT
L49BF:  STA R3

MULT_5:
L49C1:  ASL R1                  ;CHECK BIT
L49C3:  BCS MULT_2              ;ADD IT IN
L49C5:  BNE MULT_3              ;STILL SOME BITS LEFT

MULT_6:
L49C7:  LDA R3                  ;GET PRODUCT
L49C9:  CPY #$00                ;TEST SIGN AND SET CARRY
L49CB:  BPL MULT_4              ;OK
L49CD:  EOR #$FF                ;NEGATE PRODUCT
L49CF:  ADC #$00

MULT_4:
L49D1:  RTS

MULT_2:
L49D2:  LDA R3                  ;ACCUMULATE PRODUCT
L49D4:  CLC
L49D5:  ADC R2
L49D7:  STA R3

MULT_3:
L49D9:  LSR R2                  ;ADJUST MULTIPLICAND
L49DB:  BNE MULT_5              ;(MOST OF THE TIME WE SHOULD BRANCH)
L49DD:  BEQ MULT_6

;---------------------------------------[ DISTANCE HANDLERS ]---------------------------------------

RANGE:
; [note] Wrap a 16-bit position difference the short way round the screen
L49DF:  CMP #$10
L49E1:  BCC RANGE_1             ;OK
L49E3:  CMP #$F0
L49E5:  BCS RANGE_1             ;OK
L49E7:  STA R5                  ;SAVE HI BYTE

RANGE_4:
L49E9:  LDA #$00
L49EB:  SEC
L49EC:  SBC TEMP2               ;(TEMP2,A) = 0 - (TEMP2,A)
L49EE:  STA TEMP2
L49F0:  LDA #$00
L49F2:  SBC R5

RANGE_1:
L49F4:  RTS

RTST:
; [note] RANGE with the difficulty hook: is object X within range?
L49F5:  CMP #$04                ;1/8 SCREEN AWAY
L49F7:  BCC RANGE_1             ;NO
L49F9:  CMP #$FC
L49FB:  BCS RANGE_1
L49FD:  LDY BINSCR
L49FF:  CPY #$05                ;SCORE>40,000?
L4A01:  BCC RANGE               ;NO. BE EASY
L4A03:  LDY R9
L4A05:  CPY #$03                ;MORE THAN 2 ENEMIES?
L4A07:  BCC RANGE               ;NO. BE EASY
L4A09:  STA R5                  ;SAVE ACC
L4A0B:  TXA                     ;GET OBJ INDEX
L4A0C:  CPX #$21                ;CHECKING X?
L4A0E:  BCS RTST_2              ;NO
L4A10:  LSR A

RTST_2:
L4A11:  LSR A
L4A12:  ROR A                   ;PUT X/Y BIT INTO BIT 7
L4A13:  EOR R5                  ;GET SIGN OF DIFFERENCE MODIFIED BY X/Y BIT
L4A15:  BMI RANGE_4             ;NEGATE DIFFERNECE
L4A17:  LDA R5                  ;RESTORE ACC
L4A19:  RTS                     ;AND EXIT

CPUTD:
; [note] 16-bit position difference, object Y minus object X
L4A1A:  LDA OBJXL,Y             ;COMPUTE 16 BIT DIFFERENCE
L4A1D:  SEC
L4A1E:  SBC OBJXL,X
L4A21:  STA TEMP2
L4A23:  LDA OBJXH,Y
L4A26:  SBC OBJXH,X
L4A29:  RTS                     ;DONE

SCALER:
; [note] Normalise two differences, then take the angle between them
L4A2A:  STA R4                  ;SAVE HIGH Y DIFFERENCE
L4A2C:  BPL SCALER_1
L4A2E:  JSR COMP                ;($70EC)

SCALER_1:
L4A31:  STA R5                  ;SAVE ABS
L4A33:  LDA R3                  ;GET HI X
L4A35:  BPL SCALER_2
L4A37:  JSR COMP                ;($70EC)

SCALER_2:
L4A3A:  ORA R5                  ;MERGE ABS(X) OR ABS(Y)
L4A3C:  LDX #$07                ;INITIALIZE X

SCALER_4:
L4A3E:  ASL A                   ;FIND POSITION OF MSB
L4A3F:  BMI SCALER_3
L4A41:  DEX
L4A42:  BNE SCALER_4            ;UNTIL ALL 8 TESTED

SCALER_3:
L4A44:  CPX #$04                ;DIRECTION
L4A46:  BCS SCALER_7            ;SHIFT LEFT

SCALER_5:
L4A48:  LSR R3                  ;SHIFT DIFFERENCE RIGHT N PLACES
L4A4A:  ROR R2
L4A4C:  LSR R4
L4A4E:  ROR TEMP2
L4A50:  DEX
L4A51:  BPL SCALER_5
L4A53:  LDX R2                  ;PASS X DIFFERENCE
L4A55:  LDY TEMP2               ;PASS Y DIFFERENCE

SCALER_6:
L4A57:  JMP ATAN                ;($70D4)

SCALER_7:
L4A5A:  ASL R2                  ;SHIFT DIFFERENCE LEFT UNTIL BIT 15  IS SIGN
L4A5C:  ROL R3
L4A5E:  ASL TEMP2
L4A60:  ROL R4
L4A62:  INX
L4A63:  CPX #$07
L4A65:  BCC SCALER_7
L4A67:  LDX R3                  ;PASS X DIFFERENCE
L4A69:  LDY R4                  ;PASS Y DIFFERENCE
L4A6B:  BCS SCALER_6            ;(ALWAYS)

;------------------------------------[ ENEMY PICTURE HANDLERS ]-------------------------------------

TRIPIX:
; [note] Draw the special rock's picture
L4A6D:  LSR A
L4A6E:  LSR A
L4A6F:  LSR A
L4A70:  AND #$0F
L4A72:  TAX                     ;POINT TO CONTROL BYTE
L4A73:  LDA SRTIME,X            ;GET CONTROL
L4A76:  LSR A                   ;PUT SIZE INTO BIT 6
L4A77:  LDA #$00
L4A79:  ROR A
L4A7A:  ROR A
L4A7B:  STA R1                  ;SAVE IT
L4A7D:  LDA SRANG,X             ;GET ORIENTATION
L4A80:  LSR A
L4A81:  LSR A                   ;MAKE IT AN INDEX TO 1 OF 32 WORDS
L4A82:  BIT R1                  ;BIG PIX?
L4A84:  BVC TRIPIX_1            ;NOPE
L4A86:  AND #$1E                ;YEP. ZAP THE MSB

TRIPIX_1:
L4A88:  AND #$3E                ;ZAP BIT 0
L4A8A:  ORA R1                  ;MAKE IT INDEX INTO FRM JSRLS IF BIG
L4A8C:  TAY
L4A8D:  LDX TFPIX+1,Y           ;GET MSB OF JSRL
L4A90:  LDA TFPIX,Y             ;GET LSB OF JSRL
L4A93:  JMP VGADD2              ;($7CCC) STUF IT INTO VG RAM AND EXIT

;-------------------------------[ SETTIP INITIALISE SPECIAL CLUSTER ]-------------------------------

SETTIP:
; [note] Set up a special-rock cluster
L4A96:  LDA DIFCTY
L4A99:  LSR A
L4A9A:  CMP NROCKS              ;TOO MANY ROCKS?
L4A9D:  BCS SETTIP_1            ;NO

SETTIP_2:
L4A9F:  RTS                     ;TOO MANY ROCKS

SETTIP_1:
L4AA0:  LDA SROCKS              ;ONLY COME OUT AFTER 2ND WAVE
L4AA3:  CMP #$02
L4AA5:  BCC SETTIP_2
L4AA7:  LDX SPROCK              ;ALREADY HAVE SPECIALS?
L4AAA:  BNE SETTIP_2            ;YEP. DON'T LAUNCH ANYMORE
L4AAC:  LDY NROCKS              ;GET NUMBER OF ACTIVE OBJECTS

SETTIP_6:
L4AAF:  LDA OBJ,X               ;SEARCH FOR ACTIVE BUT NOT EXPLODING OBJECT
L4AB2:  BNE SETTIP_7            ;ACTIVE OR EXPLODING
L4AB4:  STX R0                  ;SAVE HIGHEST INDEX TO FREE OBJECT

SETTIP_7:
L4AB6:  BPL SETTIP_8            ;NOT EXPLODING
L4AB8:  DEY                     ;EXPLODING. DON'T COUNT IT

SETTIP_8:
L4AB9:  INX                     ;NEXT OBJ
L4ABA:  CPX #$19                ;LIMIT?
L4ABC:  BCC SETTIP_6            ;NOPE
L4ABE:  LDX PLAYR               ;POINT TO PLAYER
L4AC0:  LDA TRILE,X             ;LAUNCHED ANY THIS WAVE?
L4AC2:  BEQ SETTIP_9            ;NO. DO IT ANYWAY
L4AC4:  CPY #$03                ;FEWER THAN 3 ITEMS?
L4AC6:  BCC SETTIP_2            ;YES. DON'T LAUNCH

SETTIP_9:
L4AC8:  LDY #$1A                ;POINT TO SAUCER VELOCITIES
L4ACA:  STY TRILE,X             ;SET TRILE .NE. FOR NEXT TIME
L4ACC:  LDX R0                  ;POINT TO FREE OBJ
L4ACE:  JSR RNDPOS              ;($6A03) GET POSITION AND VELOCITY
L4AD1:  JSR RNDXYI              ;($4B3D) GET RANDOM VELOCITY
L4AD4:  LDY #$02
L4AD6:  STY HSSND               ;SIGNAL TO MAKE NOISE WHEN CHANNEL AVAIL

SETTIP_5:
L4AD8:  TYA                     ;GET LINK
L4AD9:  ASL A                   ;MOVE IT 2 BITS LEFT
L4ADA:  ASL A
L4ADB:  ORA #$42                ;SAY SPECIAL AND MEDIUM SIZE
L4ADD:  STA OBJ,X               ;SET UP
L4AE0:  INC NROCKS              ;COUNT OBJ
L4AE3:  INC SPROCK
L4AE6:  LDA ITIME,Y             ;GET INITIAL CONTROL DATA
L4AE9:  STA SRTIME,Y            ;PASS IT
L4AEC:  LDA IANG,Y              ;GET INITIAL ANGLE
L4AEF:  STA SRANG,Y
L4AF2:  LDA ITXL,Y              ;GET INTIAL POSITION OFFSET
L4AF5:  CLC
L4AF6:  ADC OBJXL,X             ;ADD IT IN
L4AF9:  STA OBJXL,X
L4AFC:  LDA ITXH,Y
L4AFF:  ADC OBJXH,X
L4B02:  STA OBJXH,X
L4B05:  LDA ITYL,Y
L4B08:  CLC
L4B09:  ADC OBJYL,X
L4B0C:  STA OBJYL,X
L4B0F:  LDA ITYH,Y
L4B12:  ADC OBJYH,X
L4B15:  STA OBJYH,X
L4B18:  DEY                     ;COUNT DOWN
L4B19:  BMI SETTIP_2            ;DONE
L4B1B:  STX R0                  ;SAVE CURRENT INDEX
L4B1D:  JSR SEARC1              ;($6D6E) GET NEXT FREE SPACE
L4B20:  STY R1                  ;SAVE Y
L4B22:  LDY R0                  ;POINT TO OLD SPACE
L4B24:  JSR CPYPOS              ;($6210) COPY POSITION PARAMETERS
L4B27:  LDY R1                  ;RESTORE Y
L4B29:  BPL SETTIP_5            ;(ALWAYS)

ITXL:
L4B2B:  .byte $00, $58, $70     ;.Xp

ITXH:
L4B2E:  .byte $00, $FF, $00     ;...

ITYL:
L4B31:  .byte $40, $50, $00     ;@P.

ITYH:
L4B34:  .byte $FF, $00, $00     ;...

ITIME:
L4B37:  .byte $83, $85, $81     ;...

IANG:
L4B3A:  .byte $F0, $98, $40     ;..@

RNDXYI:
; [note] Add a random +/-6 to each axis
L4B3D:  JSR RNDXYI_1            ;($4B43) DO THE FOLLOWING TWICE
L4B40:  STA XINC,X              ;SET UP X

RNDXYI_1:
L4B43:  LDY #$06                ;ASSUME +
L4B45:  LDA RANDOM              ;GET RANDOM #
L4B48:  BPL RNDXYI_2            ;TRUE
L4B4A:  LDY #$FA                ;ELSE SET -

RNDXYI_2:
L4B4C:  TYA
L4B4D:  STA YINC,X
L4B50:  RTS

SINCOS:
L4B51:  .byte $00, $03, $06, $09, $0C, $10, $13, $16 ;........
L4B59:  .byte $19, $1C, $1F, $22, $25, $28, $2B, $2E ;..."%(+.
L4B61:  .byte $31, $33, $36, $39, $3C, $3F, $41, $44 ;1369<?AD
L4B69:  .byte $47, $49, $4C, $4E, $51, $53, $55, $58 ;GILNQSUX
L4B71:  .byte $5A, $5C, $5E, $60, $62, $64, $66, $68 ;Z\^`bdfh
L4B79:  .byte $6A, $6B, $6D, $6F, $70, $71, $73, $74 ;jkmopqst
L4B81:  .byte $75, $76, $78, $79, $7A, $7A, $7B, $7C ;uvxyzz{|
L4B89:  .byte $7D, $7D, $7E, $7E, $7E, $7F, $7F, $7F ;}}~~~...
L4B91:  .byte $7F               ;.

;----------------------------------[ DSTROT ASTEROIDS ROTATIONS ]-----------------------------------

ROTAST:
; [note] Rewrite one rock subroutine in vector RAM (the rocks' rotation)
L4B92:  LDA FRAME               ;GET INDEX
L4B94:  AND #$03
L4B96:  TAX
L4B97:  CLC
L4B98:  ADC #$FE                ;COMPUTE ROTATION VELOCITY
L4B9A:  ADC ASTERS,X            ;ROTATE THE ROCK
L4B9C:  STA ASTERS,X            ;ACC = XXQQPPPX
L4B9E:  AND #$F0                ;CPXROT ROUTINE NEEDS ACC TO = QQQPPPXX
L4BA0:  CLC                     ;SO WE SHIFT THE QQ 1 BIT LEFT AND INSERT A
L4BA1:  ADC ASTERS,X
L4BA3:  ASL A                   ;ACC = QQ0PPPXX
L4BA4:  JSR CPXROT              ;($6EE2) COMPUTE INDEX INTO VECTOR TABLES
L4BA7:  LDA RSOURC,Y            ;Y INDEXES INTO THE TABLE OF
L4BAA:  STA R0                  ;ADDRESSES THAT POINT TO THE LIST OF VECTORS
L4BAC:  LDA RSOURC+1,Y          ;PERTAINING TO THE PICTURE. THE APPROPRIATE
L4BAF:  STA R1                  ;ADDRESS IS COPIED INTO R0,R1.
L4BB1:  TXA                     ;TO ADD VARIETY, 2 OF THE 4 ROCK PICTURES ARE
L4BB2:  ASL A                   ;DISPLAYED IN A MIRROR IMAGE FORMAT. THESE
L4BB3:  TAX                     ;INSTRUCTIONS BOTH ADJUST THE ROCK PICTURE
L4BB4:  ASL A                   ;CODE TO ADDRESS WORDS AND APPLIES THE
L4BB5:  AND #$04                ;MIRROR IMAGE. THE MIRRORING IS
L4BB7:  EOR TEMP1               ;DETERMINED BY THE CODE.
L4BB9:  STA TEMP1
L4BBB:  LDA ROCKSA,X            ;GET LSB OF JSRL
L4BBE:  ASL A                   ;MAKE IT A BYTE ADDRESS
L4BBF:  STA VGLIST
L4BC1:  LDA ROCKSA+1,X
L4BC4:  ROL A
L4BC5:  EOR #$C0                ;DROP BIT 15 AND SET BIT 14
L4BC7:  STA $04
L4BC9:  LDX #$0C                ;GET COUNT OF VECTORS
L4BCB:  JSR CPYVEC              ;($6246) MOVE VECTORS, MODIFYING AS REQUIRED
L4BCE:  JMP VGRTSL              ;($79E8) STUFF IN AN RTSL/RECURSE OR EXIT AS REQUIRED

;-------------------------------[ CHKST-CHECK FOR START/END OF GAME ]-------------------------------

CHKST:
; EXIT	(C)=SET IF STARTING A NEW GAME
L4BD1:  LDA NPLAYR
L4BD3:  BEQ CHKST_10            ;GAME NOT IN PROGRESS
L4BD5:  LDA GDELAY
L4BD7:  BNE CHKST_60            ;STAY READY MODE
L4BD9:  JMP CHKST1              ;($4CFE) WE ARE NOT IN PLAYER READY MODE

CHKST_60:
L4BDC:  DEC GDELAY
L4BDE:  JSR CHKST2              ;($6102) DISPLAY PLAYER NUMBER MESSAGE

CHKST_30:
L4BE1:  CLC
L4BE2:  RTS

CHKST_10:
L4BE3:  STA R3                  ;2 COIN MINIMUM FLAG
L4BE5:  LDA CMODE               ;GET PRICE CODE
L4BE7:  AND #$03                ;FREE PLAY?
L4BE9:  BNE CHKST_35            ;NOPE
L4BEB:  LDA #$02                ;ALWAYS HAVE 2 CREDITS
L4BED:  STA CRDT
L4BEF:  BNE CHKST_15            ;(ALWAYS)

CHKST_35:
L4BF1:  CLC
L4BF2:  ADC #$07
L4BF4:  TAY
L4BF5:  LDA UPDFLG              ;UPDATING HI-SCORE?
L4BF7:  AND $43
L4BF9:  BPL CHKST_15            ;YES. NO MESSAGE
L4BFB:  JSR VGMSG               ;($718F) GAME PRICE
L4BFE:  LDA CRDT
L4C00:  CMP #$40                ;BAD VALUE?

CHKST_CRAPOUT:
; placed by hand: DSTRD0.MAC:311 `BCS .  ;YES. CRAP OUT`. The source branches to itself without a label; NAMED here for its comment. Spins until the watchdog resets the board
L4C02:  BCS CHKST_CRAPOUT       ;YES. CRAP OUT
L4C04:  STA R0                  ;SAVE IT
L4C06:  LDY #$0B                ;CREDIT MESSAGE
L4C08:  JSR VGMSG               ;($718F)
L4C0B:  LDX #$00                ;CLEAR PRODUCT
L4C0D:  STX R1
L4C0F:  INX                     ;LDX #1
L4C10:  STX R2                  ;CONVERTER
L4C12:  SED                     ;DO THE FOLLOWING IN DECIMAL MODE

CHKST_19:
L4C13:  LSR R0                  ;GET DATA BIT
L4C15:  BCC CHKST_17            ;DON'T HAVE ONE
L4C17:  LDA R1                  ;ACCUMULATE IT
L4C19:  CLC
L4C1A:  ADC R2
L4C1C:  STA R1

CHKST_17:
L4C1E:  BEQ CHKST_18            ;DONE
L4C20:  LDA R2                  ;DOUBLE CONVERTER VALUE
L4C22:  ADC R2                  ;(CARRY S/B CLEAR HERE)
L4C24:  STA R2
L4C26:  BCC CHKST_19            ;(ALWAYS)

CHKST_18:
L4C28:  CLD                     ;BACK TO BINARY MODE
L4C29:  LDX #$00                ;NO INTENSITY CHANGE
L4C2B:  LDY #$01                ;1 BYTE TO DISPLAY
L4C2D:  LDA #$11                ;DISPLAY VALUE IN R2
L4C2F:  SEC                     ;ZERO SUPPRESS
L4C30:  JSR DIGITS              ;($7C98)
L4C33:  LDA CMODE               ;GET COIN MODES
L4C35:  AND #$03                ;ISOLATE PRICE
L4C37:  CMP #$03                ;50 CENT PLAY?
L4C39:  BNE CHKST_15            ;NO. NEVER MIND
L4C3B:  LDA CNCT
L4C3D:  LSR A                   ;ANY 1/2 CREDITS?
L4C3E:  BCC CHKST_15            ;NO
L4C40:  LDA #$20                ;YES. GET JSRL Z.5
L4C42:  LDX #$CB
L4C44:  JSR VGADD2              ;($7CCC) DRAW IN A 1/2

CHKST_15:
L4C47:  LDY #$06                ;ASSUME 'PUSH START'
L4C49:  LDX CRDT                ;CREDIT?
L4C4B:  BNE CHKST_16            ;YEP
L4C4D:  STX TWOCM               ;RESET 2 COIN MIN FLAG

CHKST_16:
L4C4F:  LDA OPTN2
L4C52:  LSR A                   ;2 COIN MINIMUM OPTION?
L4C53:  BCC CHKST_14            ;NO
L4C55:  BIT TWOCM               ;MINIMUM MET?
L4C57:  BMI CHKST_14            ;YEP
L4C59:  CPX #$01                ;2 OR MORE CREDITS?
L4C5B:  BCC CHKST_13            ;0 CREDITS
L4C5D:  BNE CHKST_14            ;2 OR MORE
L4C5F:  ROR R3                  ;1 CREDIT (CARRY=1)

CHKST_13:
L4C61:  LDY #$0C                ;POINT TO '2 COIN MINIMUM' MESSAGE
L4C63:  BNE CHKST_21

CHKST_14:
L4C65:  LDA #$FF
L4C67:  STA TWOCM               ;SIGNAL MINIMUM MET
L4C69:  CPY #$0C                ;2 COIN MIN MESSAGE?
L4C6B:  BNE CHKST_12            ;NO

CHKST_21:
L4C6D:  JSR BM                  ;($4CEF) DISPLAY MESSAGE

CHKST_11:
L4C70:  CLC
L4C71:  LDA #$00
L4C73:  STA LOUT1               ;NO LAMPS
L4C75:  RTS                     ;BUT DON'T START

CHKST_12:
L4C76:  TXA                     ;ANY CREDITS?
L4C77:  BEQ CHKST_11            ;NO DON'T START
L4C79:  JSR BM                  ;($4CEF) BLINK 'PRESS START'
L4C7C:  LDY CRDT                ;GET CREDITS
L4C7E:  LDX #$01
L4C80:  LDA STRT1
L4C83:  BMI CHKST_20            ;ONE PLAYER START
L4C85:  CPY #$02
L4C87:  BCC CHKST_40            ;ONLY 1 CREDIT
L4C89:  LDA STRT2
L4C8C:  BPL CHKST_40            ;NO START YET
L4C8E:  STA BNKSEL              ;SWITCH TO PLAYER 2
L4C91:  JSR RTS_4_42            ;($4CE6) START EA ROM
L4C94:  JSR INIT                ;($7BF5) REINITIALIZE MEMORY
L4C97:  JSR NEWAST              ;($698E) NEW ASTEROIDS
L4C9A:  JSR NEWSHP              ;($6A37) PUT SHIP IN MIDDLE
L4C9D:  LDA NHITS
L4C9F:  STA $70                 ;ENABLE 2ND PLAYER
L4CA1:  LDX #$02
L4CA3:  DEC CRDT                ;ONE CREDIT LESS

CHKST_20:
L4CA5:  STX NPLAYR              ;NUMBER OF PLAYERS
L4CA7:  DEC CRDT                ;ONE CREDIT LESS
L4CA9:  STX BNKSEL              ;PLAYER 1
L4CAC:  STX LOUT1               ;SET LAMP CODE
L4CAE:  JSR RTS_4_42            ;($4CE6) CHECK FOR EA START
L4CB1:  JSR INIT                ;($7BF5) INITIALIZE MEM
L4CB4:  JSR NEWSHP              ;($6A37) PUT SHIP IN MIDDLE
L4CB7:  LDA #$80
L4CB9:  STA GDELAY
L4CBB:  ASL A                   ;LDA I,0 SETS CARRY TOO
L4CBC:  STA PLAYR
L4CBE:  STA PLAYR2
L4CC0:  STA PLAYR3
L4CC2:  STA BC                  ;RESET BONUS ACCUMULATOR
L4CC4:  STA BCCNT               ;RESET BONUS COUNTER
L4CC6:  LDA NHITS
L4CC8:  STA HITS                ;NUMBER OF HITS ALLOWED
L4CCA:  LDA #$04
L4CCC:  STA THUMP2
L4CCE:  STA NRESET              ;RESET NOISE GENERATOR
L4CD1:  RTS                     ;EXIT WITH CARRY SET

CHKST_40:
L4CD2:  LDA FRAME
L4CD4:  AND #$0F
L4CD6:  BNE CHKST_45            ;DO NOT CHANGE LITE
L4CD8:  LDA #$01                ;ASSUME 2 PLAYER
L4CDA:  CMP CRDT                ;MORE THAN 1 CREDIT?
L4CDC:  BEQ CHKST_46            ;NO
L4CDE:  LDA #$03                ;YES

CHKST_46:
L4CE0:  EOR LOUT1
L4CE2:  STA LOUT1               ;LET NMI WRITE TO OUT1

CHKST_45:
L4CE4:  CLC

RTS_4:
; [note] Shared return
L4CE5:  RTS

RTS_4_42:
L4CE6:  LDA UPDFLG              ;ANY HI-SCORES?
L4CE8:  AND $43
L4CEA:  BMI CHKST_45            ;NO
L4CEC:  JMP STEAROM             ;($7BD9) YES. START EA ROM

BM:
; [note] Blink the two-coin-minimum message
L4CEF:  LDA TWOCM
L4CF1:  ORA R3
L4CF3:  BPL BM_1                ;DON'T BLINK
L4CF5:  LDA FRAME
L4CF7:  AND #$20                ;ON/OFF
L4CF9:  BNE RTS_4               ;OFF

BM_1:
L4CFB:  JMP VGMSG               ;($718F)

CHKST1:
; [note] Game in progress: handle game over and the player change
L4CFE:  LDA FRAME
L4D00:  AND #$3F
L4D02:  BNE CHKST1_70           ;ONLY EVERY 1 SECOND
L4D04:  LDA THUMP3
L4D07:  CMP #$08
L4D09:  BEQ CHKST1_70           ;AT FASTEST RATE NOW
L4D0B:  DEC THUMP3

CHKST1_70:
L4D0E:  LDX PLAYR
L4D10:  LDA HITS,X
L4D12:  BNE CHKST1_60           ;IF HE STILL IN GAME
L4D14:  LDA SHPTP               ;ANY OF HIS MISSILES STILL FLYING?
L4D17:  ORA $021E
L4D1A:  ORA $021F
L4D1D:  ORA $0220
L4D20:  BNE CHKST1_60           ;TORPEDO STILL ALIVE
L4D22:  LDY #$07
L4D24:  JSR VGMSG               ;($718F) GAME OVER MESSAGE
L4D27:  LDA NPLAYR
L4D29:  CMP #$02
L4D2B:  BCC CHKST1_60           ;1 PLAYER GAME
L4D2D:  JSR CHKST2              ;($6102) DISPLAY PLAYER NUMBER

CHKST1_60:
L4D30:  LDA SHPPIX
L4D33:  BNE CHKST1_80           ;STILL ALIVE

CHKST1_62:
L4D35:  LDA SDELAY
L4D38:  CMP #$80
L4D3A:  BNE CHKST1_80           ;SHIP RETURNING TO LIFE
L4D3C:  LDA #$10
L4D3E:  JSR SSBTLT              ;($6325)
L4D41:  LDX NPLAYR
L4D43:  LDA HITS
L4D45:  ORA $70
L4D47:  BEQ CHKST1_90           ;GAME IS ALL OVER
L4D49:  JSR RSAUCR              ;($6826) RESET SAUCER VALUES

CHKST1_61:
L4D4C:  DEX
L4D4D:  BEQ CHKST1_80           ;ONE PLAYER NO MESSAGE NEEDED
L4D4F:  LDA #$80
L4D51:  STA GDELAY              ;DELAY BEFORE STARTING PLAYER
L4D53:  LDA PLAYR
L4D55:  EOR #$01
L4D57:  TAX                     ;1 TO 0 AND 0 TO 1
L4D58:  LDA HITS,X
L4D5A:  BEQ CHKST1_80           ;NO HITS FOR THIS PLAYER
L4D5C:  STX PLAYR               ;SET PLAYER NUMBER
L4D5E:  TXA
L4D5F:  ROR A
L4D60:  ROR A
L4D61:  STA BNKSEL              ;SWITCH PLAYERS
L4D64:  TXA
L4D65:  ASL A
L4D66:  STA PLAYR2
L4D68:  ORA PLAYR
L4D6A:  STA PLAYR3

CHKST1_80:
L4D6C:  CLC
L4D6D:  RTS

CHKST1_90:
L4D6E:  STX LPLAYR              ;SAVE NUMBER OF PLAYERS IN THIS GAME
L4D70:  LDA #$FF
L4D72:  STA NPLAYR              ;FLAG TO UPDATE HIGH SCORES
L4D74:  LDA #$03
L4D76:  STA LOUT1               ;LET NMI WRITE TO LAMPS
L4D78:  STA BNKSEL              ;PLAYER 1
L4D7B:  BNE CHKST1_80           ;(ALWAYS)

